public boolean canArrange(int[] arr, int k) {
    int[] modCounts = new int[k];
    for (int num : arr) {
        int mod = (num % k + k) % k;
        modCounts[mod]++;
    }

    if (modCounts[0] % 2 != 0) {
        return false;
    }

    for (int i = 1; i <= k / 2; i++) {
        if (modCounts[i] != modCounts[k - i]) {
            return false;
        }
    }

    return true;
}

