public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    int n = heights.length;
    Stack<Integer> stack = new Stack<>();

    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? -1 : heights[i];
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            maxArea = Math.max(maxArea, height * width);
        }
        stack.push(i);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) return new int[0];

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int r = 0, c = 0, i = 0;

    while (i < result.length) {
        result[i++] = mat[r][c];
        if ((r + c) % 2 == 0) { // Going up
            if (c == cols - 1) r++;
            else if (r == 0) c++;
            else r--;
        } else { // Going down
            if (r == rows - 1) c++;
            else if (c == 0) r++;
            else c--;
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();

    // Find the first digit that can be swapped to get a larger number
    int i;
    for (i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, return -1 (not possible to rearrange to get a larger number)
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on the right side of (i-th digit) which is greater than digits[i]
    int j;
    for (j = digits.length - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the digits after the (i-th digit) in ascending order
    Arrays.sort(digits, i + 1, digits.length);

    // Convert the char array back to an integer
    return Integer.parseInt(new String(digits));
}

